package app.daiyu.android.domain.question

/** Stable scope supplied by the runner, not generated by this tool. Owner identifies the logical
 * runner instance; a different owner must never consume a previous runner's answer. */
data class QuestionIdentity(val conversationId: String, val runId: String, val ownerId: String, val callId: String) {
    init { listOf(conversationId, runId, ownerId, callId).forEach { require(it.isNotBlank() && it.length <= 256) } }
    /** Length-prefixed components avoid delimiter collisions. */
    val ownerPrefix: String get() = "q1:" + listOf(conversationId, runId, ownerId).joinToString("") { "${it.length}:$it" }
    val storageKey: String get() = ownerPrefix + "${callId.length}:$callId"
}
